import{_ as a,c as t,o as n,ag as s}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Debate","description":"","frontmatter":{"title":"Debate"},"headers":[],"relativePath":"general/debate.md","filePath":"general/debate.md","lastUpdated":null}'),r={name:"general/debate.md"};function i(p,e,o,l,d,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="debate" tabindex="-1">Debate <a class="header-anchor" href="#debate" aria-label="Permalink to &quot;Debate&quot;">​</a></h1><h2 id="debate-club" tabindex="-1">Debate Club <a class="header-anchor" href="#debate-club" aria-label="Permalink to &quot;Debate Club&quot;">​</a></h2><p>The purpose of the Debate Club in the Irregularchat community is to create a structured environment for constructive argumentation. This platform is designed to foster thoughtful discussions, highlight areas of agreement, understand differing perspectives and identify information gaps. Members can explore complex topics respectfully and patiently by adhering to structured engagement.</p><h3 id="key-rules-for-engagement" tabindex="-1">Key Rules for Engagement <a class="header-anchor" href="#key-rules-for-engagement" aria-label="Permalink to &quot;Key Rules for Engagement&quot;">​</a></h3><p><strong>Civility First</strong>: Always maintain a respectful tone and approach arguments in good faith. <strong>Patient Discourse</strong>: Allow ample time for responses; avoid overwhelming others with rapid-fire arguments. <strong>Focus on Arguments</strong>: Refrain from personal attacks and ad hominem tactics. <strong>Avoid Escalating Comparisons</strong>: Steer clear of extreme analogies or comparisons, such as invoking Godwin&#39;s Law. <strong>Fact-Based Discussion</strong>: Support your arguments with facts, sources, and evidence wherever possible. <strong>Spectators</strong>: Spectators may ask respectful questions but cannot present arguments or take sides.</p><h3 id="opening-prompt" tabindex="-1">Opening Prompt <a class="header-anchor" href="#opening-prompt" aria-label="Permalink to &quot;Opening Prompt&quot;">​</a></h3><p>Use this structured prompt to start a debate and define sides clearly:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## State Your Initial Position: Keep it brief and clear. Maximum of two sentences.</span></span>
<span class="line"><span>2. Create an Ephemeral Notepad and Post the Link: Use https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo</span></span>
<span class="line"><span>3. Open the Floor for Questions and Side Selection: Invite participants to join sides.</span></span>
<span class="line"><span>4. 10-Minute Argument Submission: Post your initial argument supporting your position.</span></span>
<span class="line"><span>5. Sides Are Defined: Only participants can ask further questions once positions are set.</span></span>
<span class="line"><span>6. Respectful Debate:</span></span>
<span class="line"><span>    • Use emoji reactions to show support, ask questions, or express objections.</span></span>
<span class="line"><span>    • Only those with a stated position may argue, though all may ask clarifying questions.</span></span>
<span class="line"><span>    • Engage in a constructive, respectful debate focused on the arguments.</span></span>
<span class="line"><span>Let&#39;s rumble!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="setting-up-an-ephemeral-notepad" tabindex="-1">Setting Up an Ephemeral Notepad <a class="header-anchor" href="#setting-up-an-ephemeral-notepad" aria-label="Permalink to &quot;Setting Up an Ephemeral Notepad&quot;">​</a></h3><h2 id="open-the-debate-template-here-cryptpad-debate-template" tabindex="-1">Open the debate template here: <a href="https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/" target="_blank" rel="noreferrer">Cryptpad Debate Template</a>. <a class="header-anchor" href="#open-the-debate-template-here-cryptpad-debate-template" aria-label="Permalink to &quot;Open the debate template here: [Cryptpad Debate Template](https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/).&quot;">​</a></h2><ol start="2"><li><p>Go to <em>File &gt; Copy</em> to create a new, editable version of the notepad.</p></li><li><p>Share the URL with edit access in the debate chat so participants can join.</p></li></ol><h3 id="debate-template" tabindex="-1">Debate Template <a class="header-anchor" href="#debate-template" aria-label="Permalink to &quot;Debate Template&quot;">​</a></h3><p>Use the following embedded template to facilitate the debate process:</p><p><a href="https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/embed/" target="_blank" rel="noreferrer">https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/embed/</a></p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>[Rules]</p>`,16)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
